/// base64 -> байты. Переводы строк и мусор пропускаем.
pub fn decode(s: &str) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;
    for b in s.bytes() {
        let v = match b {
            b'A'..=b'Z' => b - b'A',
            b'a'..=b'z' => b - b'a' + 26,
            b'0'..=b'9' => b - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => continue,
        };
        buf = (buf << 6) | v as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buf >> bits) as u8);
            buf &= (1u32 << bits) - 1;
        }
    }
    out
}

/// Выбирает самый большой размер, который влезает в сетку (w x h).
pub fn best_for(w: usize, h: usize) -> usize {
    let mut best = 0;
    for i in 0..VERSIONS.len() {
        if VERSIONS[i].w <= w && VERSIONS[i].h <= h {
            best = i;
        }
    }
    best
}

